import { jest, describe, test, expect, beforeEach, afterEach } from '@jest/globals'


import {
  clean,
  isValid,
  format,
  isDate,
  isNotDate,
  toDate,
  formatDate
} from './dateHelpers.js'; // Adjust path to your source file

describe('Date Utilities Unit Tests', () => {
  // Suppress console.log output generated by formatDate during tests
  beforeAll(() => {
    jest.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterAll(() => {
    console.log.mockRestore();
  });

  describe('isDate', () => {
    test('returns true for valid Date instances', () => {
      expect(isDate(new Date())).toBe(true);
      expect(isDate(new Date('2024-01-01'))).toBe(true);
    });

    test('returns false for invalid Date instances', () => {
      expect(isDate(new Date('invalid-date-string'))).toBe(false);
    });

    test('returns false for non-Date types and empty values', () => {
      expect(isDate(undefined)).toBe(false);
      expect(isDate('')).toBe(false);
      expect(isDate(null)).toBe(false);
      expect(isDate(0)).toBe(false);
      expect(isDate('2024-01-01')).toBe(false);
      expect(isDate({})).toBe(false);
      expect(isDate([])).toBe(false);
    });
  });

  describe('isNotDate', () => {
    test('inverts isDate results', () => {
      expect(isNotDate(new Date())).toBe(false);
      expect(isNotDate('2024-01-01')).toBe(true);
      expect(isNotDate(undefined)).toBe(true);
    });
  });

  describe('isValid', () => {
    test('delegates to isDate', () => {
      expect(isValid(new Date())).toBe(true);
      expect(isValid(new Date('invalid'))).toBe(false);
      expect(isValid('2024-05-15')).toBe(false);
    });
  });

  describe('toDate', () => {
    test('returns undefined for undefined input', () => {
      expect(toDate(undefined)).toBeUndefined();
    });

    test('returns the original object if it is already a valid Date', () => {
      const date = new Date(2024, 0, 15);
      expect(toDate(date)).toBe(date);
    });

    test('parses valid date strings into Date objects', () => {
      const parsed = toDate('2024-05-10');
      expect(parsed).toBeInstanceOf(Date);
      expect(isDate(parsed)).toBe(true);
    });

    test('returns undefined for numeric values and numeric strings', () => {
      // The implementation explicitly checks !isNaN(Number(value)) to exclude numbers/timestamps
      expect(toDate(1672531199000)).toBeUndefined();
      expect(toDate('123456')).toBeUndefined();
      expect(toDate(0)).toBeUndefined();
    });

    test('returns undefined for empty, null, or invalid date strings', () => {
      expect(toDate('')).toBeUndefined();
      expect(toDate(null)).toBeUndefined(); // Number(null) is 0, caught by !isNaN(Number(value))
      expect(toDate('not-a-date')).toBeUndefined();
    });
  });

  describe('clean', () => {
    test('returns Date object when value is valid', () => {
      const result = clean('2024-05-10');
      expect(result).toBeInstanceOf(Date);
    });

    test('returns undefined when value cannot be parsed and no defaultValue is passed', () => {
      expect(clean('invalid-date')).toBeUndefined();
      expect(clean(undefined)).toBeUndefined();
    });

    test('returns defaultValue fallback when value cannot be parsed', () => {
      const fallback = 'DEFAULT_FALLBACK';
      expect(clean('invalid-date', fallback)).toBe(fallback);
      expect(clean(undefined, fallback)).toBe(fallback);
    });
  });

  describe('formatDate and format', () => {
    test('returns undefined for invalid or non-date inputs', () => {
      expect(formatDate(undefined)).toBeUndefined();
      expect(formatDate('invalid-date')).toBeUndefined();
      expect(formatDate(123456789)).toBeUndefined();
    });

    test('formats valid date string as YYYY-MM-DD by default', () => {
      const date = new Date(2024, 3, 5, 8, 3, 2); // April 5, 2024
      expect(formatDate(date)).toBe('2024-04-05');
    });

    test('formats valid date with time when includeTime is true', () => {
      const date = new Date(2024, 3, 5, 8, 3, 2); // 08:03:02
      expect(formatDate(date, true)).toBe('2024-04-05 08:03:02');
    });

    test('zero-pads single-digit days, months, hours, minutes, and seconds', () => {
      const date = new Date(2024, 0, 2, 4, 5, 6); // Jan 2, 2024 04:05:06
      expect(formatDate(date, true)).toBe('2024-01-02 04:05:06');
    });

    test('format() aliases formatDate()', () => {
      const date = new Date(2024, 11, 25, 14, 30, 0); // Dec 25, 2024
      expect(format(date)).toBe('2024-12-25');
      expect(format(date, true)).toBe('2024-12-25 14:30:00');
    });
  });
});